function markup(text){return text.replaceAll('§',String.fromCharCode(60))}
function newSection(id,content){const s=el('section');s.id=id;s.className='view shell-view';s.hidden=true;s.innerHTML=markup(content);document.querySelector('footer').before(s);return s}
function display(value,digits=2){return Number.isFinite(value)?value.toFixed(digits):value===null||value===undefined?'N/A':String(value)}
function pill(value){const s=el('span',value===true?'PASS':value===false?'FAIL':'N/A');s.className='state-pill '+(value===true?'good':value===false?'bad':'unknown');return s}
function safeStorage(key,fallback=''){try{return localStorage.getItem(key)??fallback}catch{return fallback}}
function csv(headers,rows){const quote=value=>'"'+String(value??'N/A').replaceAll('"','""')+'"';return String.fromCharCode(65279)+[headers,...rows].map(row=>row.map(quote).join(',')).join(String.fromCharCode(13,10))}
function binaryLast(rows,time){let lo=0,hi=rows.length;while(hi>lo){const mid=(lo+hi)>>1;if(time>=rows[mid].at)lo=mid+1;else hi=mid}return lo-1}
function latest(rows,time){const i=binaryLast(rows||[],time);return i>=0?rows[i]:null}
function runIndex(run){let index=Platform.indices.get(run);if(index)return index;const robots={r1:[],r2:[],r3:[]};for(const sample of run.samples||[])for(const [name,p]of Object.entries(sample.poses||{})){if(!p||!Number.isFinite(p.x)||!Number.isFinite(p.y))continue;(robots[name]??=[]).push({at:sample.at,...p,line:sample.line,source_kind:sample.source_kind})}for(const values of Object.values(robots))values.sort((a,b)=>a.at-b.at);const snapshots=[];for(const event of run.semantic_events||[])snapshots.push(...event.history);snapshots.sort((a,b)=>(a.at??Infinity)-(b.at??Infinity));index={robots,snapshots,trailChunks:{}};Platform.indices.set(run,index);return index}
function currentSnapshot(run,t){return latest(runIndex(run).snapshots,t)}
function currentTask(run,robot,t){return run.records.find(r=>r.robot===robot&&Number.isFinite(r.begin)&&t>=r.begin&&(!Number.isFinite(r.end)||r.end>=t))}
function taskState(r,t){if(!r)return'无活动记录';if(Number.isFinite(r.service_finished)&&t>=r.service_finished)return'驶离 / 释放';if(Number.isFinite(r.service_started)&&t>=r.service_started)return({verify:'核验',monitor:'持续监护',pickup:'取货',deliver:'交付'})[r.role]||'服务中';if(Number.isFinite(r.stable_at)&&t>=r.stable_at)return'到达后等待';return'导航 / 到达准备'}
async function cachedRun(name,refresh=false){if(!refresh&&Platform.cache.has(name)){const value=Platform.cache.get(name);Platform.cache.delete(name);Platform.cache.set(name,value);return value}const promise=api('/api/run?name='+encodeURIComponent(name));Platform.cache.set(name,promise);try{const run=await promise;Platform.cache.set(name,run);while(Platform.cache.size>Platform.cacheLimit)Platform.cache.delete(Platform.cache.keys().next().value);return run}catch(e){Platform.cache.delete(name);throw e}}
function selectedPlan(run,t){const explicit=$('lane-plan')?.value;if(run===data&&explicit&&explicit!=='current')return run.plan_versions[Number(explicit)]||null;return latest(run.plan_versions||[],t)}
function writeDetail(value,title='原始证据与派生信息'){const drawer=$('source-drawer');drawer.open=true;$('source-title').textContent=title;$('detail').textContent=typeof value==='string'?value:JSON.stringify(value,null,2)}
async function showRaw(line,run=data){if(!run||!Number.isInteger(line))return;try{const r=await api('/api/raw?name='+encodeURIComponent(run.name)+'&line='+line);writeDetail(r.path+':'+r.line+'\n'+r.raw_text,'原始日志行（时间戳未改写）')}catch(e){error(e)}}
