$('export-metrics-csv').onclick=()=>{if(!data)return;const runs=Platform.sync.length?Platform.sync.map(i=>i.run):[data],headers=['run','recorded_strategy','tasks_completed','task_denominator','completion_rate','last_task_end_episode_s','return_end_episode_s','event_episode_s','disturbance_episode_s','planning_wall_sum_s','first_validated_sim_s','resource_conflicts','commitment_violations','trace_sha256'];saveFile('clinic-metrics.csv',csv(headers,runs.map(r=>[r.name,r.strategy,r.metrics.task_completion_numerator,r.metrics.task_completion_denominator,r.metrics.task_completion_rate,r.metrics.last_task_end_sim,r.metrics.return_end_sim,r.metrics.event_sim,r.metrics.disturbance_sim,r.metrics.planning_wall_sum,r.metrics.first_validated_sim,r.metrics.resource_conflicts,r.metrics.commitment_violations,r.sources.find(s=>s.path.endsWith('trace.jsonl'))?.sha256])),'text/csv;charset=utf-8')};
function summaryExport(){if(!data)return;saveFile(data.name.split('/').at(-1)+'-research-summary.json',{name:data.name,passed:data.passed,failure:data.failure_info,strategy:data.strategy,strategy_source:data.strategy_source,clock:data.clock,metrics:data.metrics,availability:data.availability,records:data.records,task_analysis:data.task_analysis,plan_versions:data.plan_versions,semantic_events:data.semantic_events,comparison_signature:data.comparison_signature,sources:data.sources,explanation:data.explanation,map_reference:{path:mapMeta?.source,sha256:mapMeta?.sha256,yaml_sha256:mapMeta?.yaml_sha256},nonfinite_fields:data.nonfinite_fields,notes:$('review-notes').value,limitations:'Read-only evidence and descriptive comparison. No inferred trajectories, thresholds or performance claims.'})}
$('export-summary').onclick=summaryExport;$('export').onclick=summaryExport;
async function initialize(){try{const m=await api('/api/map'),pixels=atob(m.pixels),off=document.createElement('canvas');off.width=m.width;off.height=m.height;const c=off.getContext('2d'),image=c.createImageData(m.width,m.height);for(let i=0;i!==pixels.length;i++){const gray=pixels.charCodeAt(i);image.data[i*4]=gray;image.data[i*4+1]=gray;image.data[i*4+2]=gray;image.data[i*4+3]=255}c.putImageData(image,0,0);delete m.pixels;mapMeta=m;mapRaster=off;buildGrid();await refresh();openTab(Platform.tab)}catch(e){error(e)}}
initialize();
